			mc.cache(bounds.x, bounds.y, bounds.width, bounds.height);
		
			mc1.filters = [turnRed];
			var bounds1 = mc1.nominalBounds;
			mc1.cache(bounds1.x, bounds1.y, bounds1.width, bounds1.height);
			
			mc2.filters = [turnRed];
